//! Small OS hooks that arboard doesn't cover: a cheap "has the clipboard
//! changed" counter, and the markers password managers set to ask
//! clipboard tools not to record a copy.

#[cfg(target_os = "macos")]
mod imp {
    use objc2_app_kit::NSPasteboard;

    /// Types set by password managers and other apps that don't want the
    /// copy recorded. See http://nspasteboard.org
    const SKIP_TYPES: [&str; 3] = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
    ];

    #[allow(unused_unsafe)]
    pub fn change_count() -> Option<i64> {
        let pb = unsafe { NSPasteboard::generalPasteboard() };
        Some(unsafe { pb.changeCount() } as i64)
    }

    #[allow(unused_unsafe)]
    pub fn should_skip() -> bool {
        let pb = unsafe { NSPasteboard::generalPasteboard() };
        let Some(types) = (unsafe { pb.types() }) else {
            return false;
        };
        types.iter().any(|t| SKIP_TYPES.contains(&t.to_string().as_str()))
    }
}

#[cfg(windows)]
mod imp {
    use windows_sys::Win32::System::DataExchange::{
        GetClipboardSequenceNumber, IsClipboardFormatAvailable, RegisterClipboardFormatW,
    };

    /// Formats password managers (e.g. KeePass) add to opt out of
    /// clipboard history tools.
    const SKIP_FORMATS: [&str; 2] = [
        "ExcludeClipboardContentFromMonitorProcessing",
        "Clipboard Viewer Ignore",
    ];

    pub fn change_count() -> Option<i64> {
        Some(unsafe { GetClipboardSequenceNumber() } as i64)
    }

    pub fn should_skip() -> bool {
        SKIP_FORMATS.iter().any(|name| {
            let wide: Vec<u16> = name.encode_utf16().chain(std::iter::once(0)).collect();
            unsafe {
                let format = RegisterClipboardFormatW(wide.as_ptr());
                format != 0 && IsClipboardFormatAvailable(format) != 0
            }
        })
    }
}

#[cfg(not(any(target_os = "macos", windows)))]
mod imp {
    pub fn change_count() -> Option<i64> {
        None
    }

    pub fn should_skip() -> bool {
        false
    }
}

pub use imp::{change_count, should_skip};
